        if(typ=="Film"){var symbol=Program.Tekst("▶",16,"#FFFFFF");symbol.Margin=new Thickness(0);podglad.Children.Add(new Border {Background=Program.Kolor("#88000000"),CornerRadius=new CornerRadius(16),Padding=new Thickness(8,4,8,4),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Child=symbol});
