    public static async Task<MetadaneKafelka> Metadane(Wiersz w,CancellationToken token){token.ThrowIfCancellationRequested();string klucz=w.Sciezka+"|"+w.Rozmiar+"|"+w.Zmiana.ToString("R",System.Globalization.CultureInfo.InvariantCulture);string poprzedni;lock(blokada){if(Ustawienia.KluczeMiniatur.TryGetValue(klucz,out poprzedni))klucz=poprzedni;}lock(blokada){MetadaneKafelka gotowe;if(pamiec.TryGetValue(klucz,out gotowe))return gotowe;}await pracownicy.WaitAsync(token);try{return await Task.Run(()=>{token.ThrowIfCancellationRequested();var dane=new MetadaneKafelka();try{var plik=new FileInfo(w.Sciezka);if(!plik.Exists||(plik.Attributes&(FileAttributes.ReparsePoint|FileAttributes.Offline))!=0||(((int)plik.Attributes)&0x440000)!=0)return dane;dane.Utworzenie=plik.CreationTime;string typ=Kategoria(w);if(typ=="Film"||typ=="Audio"||typ=="Dokument")MetadaneWindows.Uzupelnij(w,dane);if(typ=="Zdjęcie"){
            string katalog=Path.Combine(Program.Katalog,"dane","miniatury");Directory.CreateDirectory(katalog);string nazwa;using(var hash=System.Security.Cryptography.SHA256.Create())nazwa=BitConverter.ToString(hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes(klucz))).Replace("-","")+".png";string sciezka=Path.Combine(katalog,nazwa);
            if(File.Exists(sciezka)){var obraz=new BitmapImage();obraz.BeginInit();obraz.CacheOption=BitmapCacheOption.OnLoad;obraz.UriSource=new Uri(sciezka);obraz.EndInit();obraz.Freeze();dane.Miniatura=obraz;}
            else if(plik.Length<=128*1024*1024){using(var strumien=new FileStream(w.Sciezka,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){var dekoder=BitmapDecoder.Create(strumien,BitmapCreateOptions.DelayCreation,BitmapCacheOption.None);dane.Szerokosc=dekoder.Frames[0].PixelWidth;dane.Wysokosc=dekoder.Frames[0].PixelHeight;if((long)dane.Szerokosc*dane.Wysokosc>100000000)return dane;strumien.Position=0;var obraz=new BitmapImage();obraz.BeginInit();obraz.CacheOption=BitmapCacheOption.OnLoad;if(dane.Szerokosc>=dane.Wysokosc)obraz.DecodePixelWidth=256;else obraz.DecodePixelHeight=256;obraz.StreamSource=strumien;obraz.EndInit();obraz.Freeze();dane.Miniatura=obraz;if(RezerwujMiniature(katalog)){var zapis=new PngBitmapEncoder();zapis.Frames.Add(BitmapFrame.Create(obraz));using(var cel=new FileStream(sciezka,FileMode.CreateNew,FileAccess.Write,FileShare.Read))zapis.Save(cel);File.WriteAllText(sciezka+".json",Program.Json.Serialize(new[]{dane.Szerokosc,dane.Wysokosc}));}}}
            if(dane.Szerokosc==0&&File.Exists(sciezka+".json")){int[] wymiary=Program.Json.Deserialize<int[]>(File.ReadAllText(sciezka+".json"));dane.Szerokosc=wymiary[0];dane.Wysokosc=wymiary[1];}
        }}catch(IOException){}catch(UnauthorizedAccessException){}catch(NotSupportedException){}catch(System.Runtime.InteropServices.COMException){}catch(System.IO.FileFormatException){}lock(blokada){if(!pamiec.ContainsKey(klucz)){pamiec[klucz]=dane;kolejnosc.Enqueue(klucz);while(kolejnosc.Count>256)pamiec.Remove(kolejnosc.Dequeue());}}return dane;});}finally{pracownicy.Release();}}
